// ============================================================
// Media Validator — фильтрует каналы по совместимости с медиа.
// (MEMES GENERATION workflow)
//
// Каждая платформа имеет свои ограничения на количество
// картинок в посте и максимальную длительность видео.
// Если контент новости не укладывается в лимиты платформы,
// канал этой платформы исключается из списка.
// ============================================================

// Лимиты платформ:
// maxImages — максимальное кол-во картинок в одном посте
// maxVideoDuration — максимальная длительность видео в секундах (null = без ограничений)
const PLATFORM_LIMITS = {
  'tg':        { maxImages: 10, maxVideoDuration: null },
  'telegram':  { maxImages: 10, maxVideoDuration: null },
  'instagram': { maxImages: 20, maxVideoDuration: 60 },    // 1 мин на слайд
  'facebook':  { maxImages: 10, maxVideoDuration: 14400 },  // 240 мин
  'x':         { maxImages: 4,  maxVideoDuration: null },
  'threads':   { maxImages: 20, maxVideoDuration: 300 },    // 5 мин
  'linkedin':  { maxImages: 10, maxVideoDuration: 600 },    // 10 мин
  'discord':   { maxImages: 10, maxVideoDuration: null }
};

// Получаем данные новости из предыдущих нод
let news;
try { news = $('Start trigger').first().json; } catch(e) {}
if (!news) return items; // если данных нет — пропускаем все каналы без фильтрации

const picType = news.pic_type;

// Парсим pic_info — JSON с метаданными медиа (images[], duration, width, height)
let picInfo = {};
try { picInfo = JSON.parse(news.pic_info || '{}'); } catch(e) {}

// Определяем количество картинок в новости
let imageCount = 1;
if (picType === 'group_of_photo') {
  // Для группы фото — считаем из pic_info.images или из pic_url (массив file_id)
  if (Array.isArray(picInfo.images)) {
    imageCount = picInfo.images.length;
  } else if (news.pic_url) {
    try {
      const urls = JSON.parse(news.pic_url);
      if (Array.isArray(urls)) imageCount = urls.length;
    } catch (e) {}
  }
}

// Длительность видео в секундах (приходит в pic_info.duration)
const videoDuration = picInfo.duration || null;
const isVideo = ['video', 'video_url', 'video_file_id'].includes(picType);

// Фильтруем каналы: оставляем только те, где контент укладывается в лимиты
return items.filter(item => {
  const channelType = (item.json.channel_type || '').toLowerCase();
  const limits = PLATFORM_LIMITS[channelType];

  // Неизвестная платформа — пропускаем без фильтрации
  if (!limits) return true;

  // Проверка лимита картинок
  if (limits.maxImages && imageCount > limits.maxImages) return false;

  // Проверка длительности видео
  if (isVideo && limits.maxVideoDuration && videoDuration > limits.maxVideoDuration) return false;

  return true;
});

// Parse pic_url JSON array and create items for each file_id
const picUrl = $('Update a row').first().json.pic_url;
let fileIds = [];

try {
  fileIds = JSON.parse(picUrl);
} catch (e) {
  // If not valid JSON, treat as single item
  fileIds = [picUrl];
}

if (!Array.isArray(fileIds)) {
  fileIds = [fileIds];
}

// Return items with original data plus individual file_id
return fileIds.map((fileId, index) => ({
  json: {
    ...$json,
    current_file_id: fileId,
    file_index: index,
    total_files: fileIds.length
  }
}));

